import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第二卷 回潮 · 第13章 雾散","description":"","frontmatter":{},"headers":[],"relativePath":"第13章_雾散.md","filePath":"第13章_雾散.md"}'),r={name:"第13章_雾散.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第二卷-回潮-·-第13章-雾散" tabindex="-1">第二卷 回潮 · 第13章 雾散 <a class="header-anchor" href="#第二卷-回潮-·-第13章-雾散" aria-label="Permalink to &quot;第二卷 回潮 · 第13章 雾散&quot;">​</a></h1><p>那年春天风还带着凉意，教室窗户半开着，外面的玉兰花落了一地，白得晃眼。</p><p>班主任抱着一叠纸走进来，粉笔灰落在他袖口上，他拍了拍，才开口说市三中这学期要回南雾借址，网课也在那边上。</p><p>全班一下静了几秒，随后椅子响动，纸张翻动，有人小声欢呼，有人叹气。</p><p>领完通知我去机房帮着搬网线。那间借来的教室桌子全挤在一起，地上堆着成捆的线，一圈一圈绑着。我和陈默一人抬一头往里搬，线圈硌着掌心，又硬又凉。我们把线顺着墙角捋直，用胶带一段一段贴在地上，胶带撕开时呲的一声，粘在手上带着纸毛，墙角的灰被风带起来，呛得鼻尖发痒。</p><p>我低着头转笔，笔帽上的缺口硌着指腹，心里并没有太多起伏，直到那张名单传到我手里。</p><p>纸很薄，油墨味很重，边角被前排同学捏得发皱。我一行一行往下看，目光落在自己的名字上，后面跟着两个字，南雾。</p><p>名单边被汗沾得有点透明，油墨味混着前排同学书包里橘子的甜香，一股一股往鼻子里钻。窗外的雨刚停，地面的潮气贴着裤脚往上爬，凉凉的。</p><p>看到南雾二字的那一瞬，心跳像是漏了一拍，耳朵里嗡的一声，周围的说话声忽然远了。</p><p>南雾中学的走廊，潮湿的青苔，雨后铁门上的锈味，还有放学时响起的那串钥匙铃铛，一下全涌了上来。</p><p>我把名单往后递，指尖有点发麻，同桌问我怎么了，我摇摇头，说没事，声音轻得自己都快听不见。</p><p>课后我去水房接热水，队伍排到走廊拐角。水龙头喷出大团白气，扑在脸上先热后凉，瓷砖上结着薄薄的水珠，混着铁锈的凉味。我把杯子口对准龙头，看着白汽在杯里打旋，指尖被烫得缩了一下，又慢慢暖过来。身后有人喊让一下，铃铛好像也响了一声，很轻，混在水声里没听真。</p><p>下课后顾远挤到我桌前，胳膊搭在我肩上，笑着说这下好了，咱们回老地方。</p><p>我没接话，把书一本本塞进书包，动作比平时慢，脑子里全是雾山市清晨的雾，浓得化不开，走两步就看不见人。</p><p>顾远看我不说话，用胳膊肘碰我，压低声音说名单我看了，有她在的那个班也一起过去。</p><p>我手顿了一下，拉链拉到一半卡住，用了点力才拉上，金属齿咬合的声音很脆。</p><p>那天晚上回宿舍，风从阳台灌进来，带着洗衣粉的香气和远处食堂的油烟味。</p><p>陈默坐在床边擦鞋，问我去南雾要带什么，我说随便收两件衣服就行。</p><p>林小满在上铺探出头，说听说南雾那边教室很旧，窗户关不严。</p><p>我没解释，把箱子从床底拖出来，轮子在水泥地上滚出沉闷的响。</p><p>箱底铺着一件洗得发白的外套，我把课本放进去，又放了一瓶薄荷水。</p><p>顾远推门进来，手里拿着两瓶橘子汽水，瓶身冰凉，往我桌上一放，发出轻响。</p><p>他把吸管插好，推到我面前，说江苒以前最爱喝这个，你忘了。</p><p>听到那个名字，我喉咙紧了一下，汽水的甜香飘过来，气泡在瓶口轻轻炸开，细小的声音。</p><p>我说没忘。</p><p>顾远在我对面坐下，椅子腿蹭着地面，吱的一声，他盯着我看了很久，忽然问，你打算一直躲着吗。</p><p>我拧着薄荷水的盖子，拧紧又松开，手指上全是凉意，说没躲，只是不知道见面说什么。</p><p>我把箱子合上，扣子扣紧，心里那点酸胀被压了下去。</p><p>我把箱子里那件旧外套抖开，抖出细细的灰，混着洗衣粉的淡淡香。顾远看我叠得慢，说，收个箱子都跟做卷子似的，一个角要压三遍。我说怕皱，他笑了一下，说皱了再抖开就是，别压坏了纸条。 那一瞬我忽然想起初三那个枇杷的下午，她把纸条递过来时指尖也是这样抖了一下，很轻，却让我记到现在。想起就心里一紧，像被潮乎乎的风掠了一下，凉凉的。</p><p>夜里熄灯后，宿舍很静，只有走廊尽头水房滴水的声音，一下，又一下。</p><p>夜里我和陈默去楼下小卖部买豆浆，宋阿婆把热杯递过来，杯壁烫手，豆香浓得扑在脸上。我小口喝着，舌尖有点烫，喉咙却稳了些，风从操场吹来，带着雨后草叶被踩碎后的腥气，混着豆浆的热，缠在鼻尖。</p><p>我睡不着，摸出床头的那张枇杷纸条，纸面已经很软了，边缘起毛，摸上去像叶子的背面。</p><p>那是她以前夹在书里的，上面画了一颗小小的枇杷，旁边写着很甜，要分你一半。</p><p>车站的早点摊冒着白气，豆浆的热混着油饼的香，一阵一阵往人堆里钻。有人提着行李来回找车，輪子滚过湿地面闷闷地响。</p><p>第二天清晨，我把那张纸条折好，夹进最常翻的那本书里。</p><p>顾远在门口喊我，说车快来了，快点。</p><p>我拉着箱子出门，轮子压过走廊的地砖，震得手心发麻。</p><p>上车前我去洗手池洗手，水是凉的，冲在手背上激得起一层鸡皮。池边放着一块旧毛巾，半湿，带着淡淡的肥皂味，我擦了两下，指尖还是凉的，却觉得清醒了些。</p><p>楼下聚集了很多同学，行李堆在一起，拉链声，说话声，塑料袋摩擦声，混成一片。</p><p>陈默帮我把箱子搬上车，我找了个靠窗的位置坐下，玻璃很凉。</p><p>顾远坐在我旁边，递给我一颗折纸星星，边角压得很平，纸面上有淡淡的香味。</p><p>他说是林小满折的，给每个人都折了一颗，人人有，不数在她那一罐里。</p><p>顾远忽然转头看我，眼睛很亮，声音压得很低，却很清楚。</p><p>他说沈聿，别躲了，这次回南雾，该说的话就说，该见的人就见。</p><p>我看着窗外不断后退的田野，风吹过，带着青草和泥土的腥气。</p><p>风从车窗缝钻进来，带着雨后田埂的腥气和柳叶的青气，凉凉的贴在脸上，吹得眼角有点酸。</p><p>车子转过一个弯，远处出现一片灰色的屋顶，雾气还没散尽，罩在上面，像盖了一层纱。</p><p>有人喊了一声，南雾到了。</p><p>我把衣领往上拉了拉，潮气贴在脖颈上有点痒，书包带勒得肩膀发紧，却不敢松开，怕松开就漏了那张纸条的热气。</p><p>我心口一紧，喉咙发干，下意识摸了摸书里的那张纸条，纸角硬硬地硌着指尖。</p><p>顾远拍拍我的背，力道很重，说走吧。</p><p>校门口的地上积着薄薄一层水，光一照晃得人睁不开眼，鞋底踩过去啪啪响，溅起的水珠落在裤脚上凉凉的。</p><p>我踩着湿漉漉的地面往下走，鞋底沾了泥，空气又凉又软，吸进肺里带着草叶被踩碎后的清苦。书包带勒着肩膀，手指一直按着那本书，怕风把纸条吹皱，心跳快得压不住，掌心全是汗。</p><p>车门打开，凉气涌进来，混着潮湿的泥土味和远处飘来的炊烟味，我听见风里有一串很轻的铃铛声。</p><p>我抬头往校门口看，人群晃动中，有个身影站在雾里，手里晃着钥匙，笑得明亮。</p><p>而我的箱子里，那张枇杷纸条正被风吹得轻轻翻动，像在等一句迟到了很久的话。</p>',56)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
